import type * as ContractTypes from '../../contracts';

import type * as AppConstants from '../../common/constants';
import { AppUtils } from '../../../app-utils';

export interface AssetBorrowPricingPreview {
  amount: number;
  currency: string;
  rows: readonly AssetBorrowPricingSummaryRow[];
}

export interface AssetBorrowPricingSummaryRow {
  key: string;
  label: string;
  detail?: string | null;
  amount: number;
  currency: string;
  multiplier?: number | null;
}

export interface AssetBorrowPricingOptions {
  pricing: ContractTypes.PricingConfig | null | undefined;
  totalQuantity: number;
  requestedQuantity: number;
  startAtIso: string;
  endAtIso: string;
  requests?: readonly ContractTypes.AssetMemberRequestDTO[];
}

export class PricingBuilder {
  static createDefaultPricingConfig(
    context: 'event' | 'asset' | 'subevent' = 'event'
  ): ContractTypes.PricingConfig {
    return {
      enabled: false,
      mode: 'fixed',
      basePrice: 0,
      currency: 'USD',
      taxMode: 'excluded',
      chargeType: 'per_attendee',
      quantityRulesEnabled: false,
      quantityRules: [],
      minPrice: null,
      maxPrice: null,
      rounding: 'none',
      demandRulesEnabled: false,
      demandRules: [],
      timeRulesEnabled: false,
      timeRules: [],
      cancellationPolicy: {
        enabled: false,
        rules: []
      },
      slotPricingEnabled: false,
      slotOverrides: [],
      audience: {
        enabled: false,
        memberPrice: null,
        vipPrice: null,
        inviteOnlyDiscountPercent: null,
        promoCodes: [],
        soldOutLabel: 'Show "Sold Out"'
      }
    };
  }

  static clonePricingConfig(
    pricing: ContractTypes.PricingConfig | null | undefined
  ): ContractTypes.PricingConfig {
    const normalized = pricing ?? this.createDefaultPricingConfig();
    return {
      ...normalized,
      quantityRules: (normalized.quantityRules ?? []).map(rule => ({
        ...rule,
        action: { ...rule.action }
      })),
      demandRules: (normalized.demandRules ?? []).map(rule => ({
        ...rule,
        action: { ...rule.action },
        slotIds: [...(rule.slotIds ?? [])]
      })),
      timeRules: (normalized.timeRules ?? []).map(rule => ({
        ...rule,
        action: { ...rule.action },
        slotIds: [...(rule.slotIds ?? [])]
      })),
      cancellationPolicy: {
        enabled: normalized.cancellationPolicy?.enabled === true,
        rules: (normalized.cancellationPolicy?.rules ?? []).map(rule => ({
          ...rule
        }))
      },
      slotOverrides: (normalized.slotOverrides ?? []).map(item => ({ ...item })),
      audience: {
        ...normalized.audience,
        promoCodes: (normalized.audience?.promoCodes ?? []).map(code => ({
          ...code,
          action: { ...code.action }
        }))
      }
    };
  }

  static normalizePricingConfig(
    value: unknown,
    options: {
      context?: 'event' | 'asset' | 'subevent';
      slotCatalog?: readonly ContractTypes.PricingSlotReference[];
      allowSlotFeatures?: boolean;
      allowedChargeTypes?: readonly AppConstants.PricingChargeType[];
      preserveEmptyPromoCodes?: boolean;
    } = {}
  ): ContractTypes.PricingConfig {
    const context = options.context ?? 'event';
    const allowSlotFeatures = options.allowSlotFeatures ?? context === 'event';
    const slotCatalog = allowSlotFeatures ? (options.slotCatalog ?? []) : [];
    const fallback = this.createDefaultPricingConfig(context);
    const source = (typeof value === 'object' && value !== null)
      ? value as Record<string, unknown>
      : {};
    const audienceSource = (typeof source['audience'] === 'object' && source['audience'] !== null)
      ? source['audience'] as Record<string, unknown>
      : {};

    const normalized: ContractTypes.PricingConfig = {
      enabled: this.normalizeBoolean(
        source['enabled'],
        this.hasMeaningfulPricingContent(source)
      ),
      mode: this.normalizeMode(source['mode']),
      basePrice: this.normalizeMoney(source['basePrice'] ?? source['amount']) ?? fallback.basePrice,
      currency: this.normalizeCurrency(source['currency']) || fallback.currency,
      taxMode: this.normalizeTaxMode(source['taxMode']) ?? fallback.taxMode,
      chargeType: this.normalizeChargeType(source['chargeType']) ?? fallback.chargeType,
      quantityRulesEnabled: this.normalizeBoolean(
        source['quantityRulesEnabled'],
        Array.isArray(source['quantityRules']) && source['quantityRules'].length > 0
      ),
      quantityRules: this.normalizeQuantityRules(source['quantityRules']),
      minPrice: this.normalizeMoney(source['minPrice']),
      maxPrice: this.normalizeMoney(source['maxPrice']),
      rounding: this.normalizeRounding(source['rounding']) ?? fallback.rounding,
      demandRulesEnabled: this.normalizeBoolean(
        source['demandRulesEnabled'],
        Array.isArray(source['demandRules']) && source['demandRules'].length > 0
      ),
      demandRules: this.normalizeDemandRules(source['demandRules']),
      timeRulesEnabled: this.normalizeBoolean(
        source['timeRulesEnabled'],
        Array.isArray(source['timeRules']) && source['timeRules'].length > 0
      ),
      timeRules: this.normalizeTimeRules(source['timeRules']),
      cancellationPolicy: this.normalizeCancellationPolicy(source['cancellationPolicy']),
      slotPricingEnabled: this.normalizeBoolean(
        source['slotPricingEnabled'],
        Array.isArray(source['slotOverrides']) && source['slotOverrides'].length > 0
      ),
      slotOverrides: this.normalizeSlotOverrides(source['slotOverrides']),
      audience: {
        enabled: this.normalizeBoolean(
          audienceSource['enabled'],
          Array.isArray(audienceSource['promoCodes']) && audienceSource['promoCodes'].length > 0
        ),
        memberPrice: this.normalizeMoney(audienceSource['memberPrice']),
        vipPrice: this.normalizeMoney(audienceSource['vipPrice']),
        inviteOnlyDiscountPercent: this.normalizePercent(audienceSource['inviteOnlyDiscountPercent']),
        promoCodes: this.normalizePromoCodes(
          audienceSource['promoCodes'],
          options.preserveEmptyPromoCodes === true
        ),
        soldOutLabel: this.normalizeText(audienceSource['soldOutLabel']) || fallback.audience.soldOutLabel
      }
    };

    const allowedChargeTypes = this.allowedChargeTypesForContext(
      context,
      allowSlotFeatures,
      options.allowedChargeTypes
    );
    normalized.chargeType = allowedChargeTypes.includes(normalized.chargeType)
      ? normalized.chargeType
      : allowedChargeTypes[0] ?? fallback.chargeType;

    const slotCatalogIds = new Set(
      slotCatalog
        .map(item => this.normalizeText(item.id))
        .filter(item => item.length > 0)
    );
    normalized.demandRules = normalized.demandRules.map(rule =>
      this.sanitizeRuleScope(rule, slotCatalogIds, allowSlotFeatures)
    );
    normalized.timeRules = normalized.timeRules.map(rule =>
      this.sanitizeRuleScope(rule, slotCatalogIds, allowSlotFeatures)
    );

    if (!allowSlotFeatures || slotCatalogIds.size === 0) {
      normalized.slotPricingEnabled = false;
      normalized.slotOverrides = [];
    }

    if (normalized.maxPrice !== null && normalized.minPrice !== null && normalized.maxPrice < normalized.minPrice) {
      normalized.maxPrice = normalized.minPrice;
    }

    return this.syncSlotOverrides(normalized, slotCatalog);
  }

  static compactPricingConfig(
    pricing: ContractTypes.PricingConfig | null | undefined,
    options: {
      context?: 'event' | 'asset' | 'subevent';
      slotCatalog?: readonly ContractTypes.PricingSlotReference[];
      allowSlotFeatures?: boolean;
      allowedChargeTypes?: readonly AppConstants.PricingChargeType[];
    } = {}
  ): ContractTypes.PricingConfig {
    return this.normalizePricingConfig(pricing, {
      ...options,
      preserveEmptyPromoCodes: false
    });
  }

  static syncSlotOverrides(
    pricing: ContractTypes.PricingConfig | null | undefined,
    slotCatalog: readonly ContractTypes.PricingSlotReference[] = []
  ): ContractTypes.PricingConfig {
    const next = this.clonePricingConfig(pricing);
    const catalogById = new Map(
      slotCatalog.map(item => [this.normalizeText(item.id), item] as const).filter(entry => Boolean(entry[0]))
    );

    next.slotOverrides = next.slotOverrides
      .map((item, index) => {
        const slotId = this.normalizeText(item.slotId);
        const linked = slotId ? catalogById.get(slotId) ?? null : null;
        const label = linked?.label?.trim() || this.normalizeText(item.label) || `Slot ${index + 1}`;
        return {
          ...item,
          id: this.normalizeText(item.id) || `slot-override-${index + 1}`,
          slotId: slotId || null,
          label,
          startAt: linked?.startAt ?? item.startAt ?? null,
          endAt: linked?.endAt ?? item.endAt ?? null,
          currency: this.normalizeCurrency(item.currency) || next.currency,
          price: this.normalizeMoney(item.price)
        };
      })
      .filter((item, index, source) => source.findIndex(candidate => candidate.id === item.id) === index);

    return next;
  }

  static resolveAssetBorrowPricing(options: AssetBorrowPricingOptions): AssetBorrowPricingPreview {
    const normalized = this.compactPricingConfig(options.pricing, {
      context: 'asset',
      allowSlotFeatures: false
    });
    const currency = normalized.currency?.trim() || 'USD';
    if (!normalized.enabled) {
      return {
        amount: 0,
        currency,
        rows: []
      };
    }

    const totalQuantity = Math.max(1, Math.trunc(Number(options.totalQuantity) || 1));
    const requestedQuantity = Math.max(1, Math.trunc(Number(options.requestedQuantity) || 1));
    const overlappingCommitted = (options.requests ?? [])
      .filter(request => request.status === 'accepted' || request.requestKind === 'manual')
      .filter(request => request.booking?.inventoryApplied !== true)
      .filter(request => this.isPricingWindowOverlap(request, options.startAtIso, options.endAtIso))
      .reduce((sum, request) => sum + this.assetRequestQuantity(request), 0);
    const capacityFilledPercent = Math.round(
      (Math.min(totalQuantity, overlappingCommitted + requestedQuantity) / totalQuantity) * 100
    );
    const hoursUntilStart = this.resolveHoursUntilStart(options.startAtIso);
    const billableDays = this.resolveAssetBorrowBillableDays(options.startAtIso, options.endAtIso);
    const rows: AssetBorrowPricingSummaryRow[] = [{
      key: 'base',
      label: 'pricing.asset.daily.rate',
      detail: null,
      amount: normalized.basePrice,
      currency,
      multiplier: 1
    }];

    let nextPrice = normalized.basePrice;
    if (normalized.quantityRulesEnabled) {
      for (const rule of normalized.quantityRules) {
        if (requestedQuantity < rule.minQuantity) {
          continue;
        }
        const previousPrice = nextPrice;
        nextPrice = this.applyPricingAction(nextPrice, rule.action);
        rows.push({
          key: `quantity-rule:${rule.id}`,
          label: 'pricing.quantity.adjustment',
          detail: `${rule.minQuantity}+ · ${this.describePricingAction(rule.action)}`,
          amount: this.roundMoney(nextPrice - previousPrice),
          currency,
          multiplier: 1
        });
      }
    }
    if ((normalized.mode === 'demand-based' || normalized.mode === 'hybrid') && normalized.demandRulesEnabled) {
      for (const rule of normalized.demandRules) {
        if (this.matchesPricingDemandRule(rule, capacityFilledPercent)) {
          const previousPrice = nextPrice;
          nextPrice = this.applyPricingAction(nextPrice, rule.action);
          rows.push({
            key: `demand:${rule.id}`,
            label: 'pricing.demand.adjustment',
            detail: `${capacityFilledPercent}% · ${this.describePricingAction(rule.action)}`,
            amount: this.roundMoney(nextPrice - previousPrice),
            currency,
            multiplier: 1
          });
        }
      }
    }
    if ((normalized.mode === 'time-based' || normalized.mode === 'hybrid') && normalized.timeRulesEnabled) {
      for (const rule of normalized.timeRules) {
        if (this.matchesPricingTimeRule(rule, hoursUntilStart, options.startAtIso)) {
          const previousPrice = nextPrice;
          nextPrice = this.applyPricingAction(nextPrice, rule.action);
          rows.push({
            key: `time:${rule.id}`,
            label: 'pricing.time.adjustment',
            detail: `${this.describePricingTimeCondition(rule)} · ${this.describePricingAction(rule.action)}`,
            amount: this.roundMoney(nextPrice - previousPrice),
            currency,
            multiplier: 1
          });
        }
      }
    }

    if (normalized.minPrice !== null) {
      const previousPrice = nextPrice;
      nextPrice = Math.max(normalized.minPrice, nextPrice);
      if (nextPrice !== previousPrice) {
        rows.push({
          key: 'min-price',
          label: 'pricing.minimum',
          detail: null,
          amount: this.roundMoney(nextPrice - previousPrice),
          currency,
          multiplier: 1
        });
      }
    }
    if (normalized.maxPrice !== null) {
      const previousPrice = nextPrice;
      nextPrice = Math.min(normalized.maxPrice, nextPrice);
      if (nextPrice !== previousPrice) {
        rows.push({
          key: 'max-price',
          label: 'pricing.maximum',
          detail: null,
          amount: this.roundMoney(nextPrice - previousPrice),
          currency,
          multiplier: 1
        });
      }
    }

    const roundedUnitPrice = this.applyPricingRounding(nextPrice, normalized.rounding);
    if (roundedUnitPrice !== nextPrice) {
      rows.push({
        key: 'rounding',
        label: 'pricing.rounding',
        detail: null,
        amount: this.roundMoney(roundedUnitPrice - nextPrice),
        currency,
        multiplier: 1
      });
    }
    const durationPrice = this.roundMoney(roundedUnitPrice * billableDays);
    if (billableDays > 1) {
      rows.push({
        key: 'duration',
        label: 'pricing.asset.billed.duration',
        detail: null,
        amount: this.roundMoney(roundedUnitPrice * (billableDays - 1)),
        currency,
        multiplier: billableDays
      });
    }
    const quantityMultiplier = normalized.chargeType === 'per_attendee'
      ? requestedQuantity
      : 1;
    if (quantityMultiplier > 1) {
      rows.push({
        key: 'quantity',
        label: 'pricing.asset.items',
        detail: null,
        amount: this.roundMoney(durationPrice * (quantityMultiplier - 1)),
        currency,
        multiplier: quantityMultiplier
      });
    }
    return {
      amount: this.roundMoney(durationPrice * quantityMultiplier),
      currency,
      rows
    };
  }

  private static matchesPricingDemandRule(
    rule: ContractTypes.PricingDemandRule,
    capacityFilledPercent: number
  ): boolean {
    if (rule.operator === 'lte') {
      return capacityFilledPercent <= rule.capacityFilledPercent;
    }
    return capacityFilledPercent >= rule.capacityFilledPercent;
  }

  private static matchesPricingTimeRule(
    rule: ContractTypes.PricingTimeRule,
    hoursUntilStart: number,
    comparisonIso: string
  ): boolean {
    if (rule.trigger === 'specific_date') {
      const start = `${rule.specificDateStart ?? ''}`.trim();
      const end = `${rule.specificDateEnd ?? ''}`.trim();
      if (!start || !end || !comparisonIso) {
        return false;
      }
      const comparisonDate = comparisonIso.slice(0, 10);
      return comparisonDate >= start && comparisonDate <= end;
    }
    if (rule.trigger === 'hours_before_start') {
      return hoursUntilStart <= Math.max(0, Number(rule.offsetValue) || 0);
    }
    const dayWindowHours = Math.max(0, Number(rule.offsetValue) || 0) * 24;
    return hoursUntilStart <= dayWindowHours;
  }

  private static applyPricingAction(currentPrice: number, action: ContractTypes.PricingAction): number {
    const value = Number(action.value) || 0;
    if (action.kind === 'set_exact_price') {
      return Math.max(0, value);
    }
    if (action.kind === 'increase_amount') {
      return Math.max(0, currentPrice + value);
    }
    if (action.kind === 'decrease_amount') {
      return Math.max(0, currentPrice - value);
    }
    const percent = value / 100;
    if (action.kind === 'decrease_percent') {
      return Math.max(0, currentPrice * (1 - percent));
    }
    return Math.max(0, currentPrice * (1 + percent));
  }

  private static describePricingAction(action: ContractTypes.PricingAction): string {
    const value = Math.max(0, Number(action.value) || 0);
    switch (action.kind) {
      case 'set_exact_price':
        return `= ${value}`;
      case 'increase_amount':
        return `+${value}`;
      case 'decrease_amount':
        return `-${value}`;
      case 'decrease_percent':
        return `-${value}%`;
      default:
        return `+${value}%`;
    }
  }

  private static describePricingTimeCondition(rule: ContractTypes.PricingTimeRule): string {
    if (rule.trigger === 'specific_date') {
      return `${rule.specificDateStart ?? ''} – ${rule.specificDateEnd ?? ''}`.trim();
    }
    const value = Math.max(0, Number(rule.offsetValue) || 0);
    return rule.trigger === 'hours_before_start' ? `≤ ${value}h` : `≤ ${value}d`;
  }

  private static roundMoney(value: number): number {
    return Math.round(value * 100) / 100;
  }

  private static applyPricingRounding(price: number, rounding: AppConstants.PricingRoundingMode): number {
    if (rounding === 'whole') {
      return Math.round(price);
    }
    if (rounding === 'half') {
      return Math.round(price * 2) / 2;
    }
    return Math.round(price * 100) / 100;
  }

  private static resolveHoursUntilStart(startAtIso: string): number {
    const start = AppUtils.isoLocalDateTimeToDate(startAtIso);
    if (!start) {
      return 0;
    }
    return Math.max(0, Math.round((start.getTime() - Date.now()) / (60 * 60 * 1000)));
  }

  private static resolveAssetBorrowBillableDays(startAtIso: string, endAtIso: string): number {
    const start = AppUtils.isoLocalDateTimeToDate(startAtIso);
    const end = AppUtils.isoLocalDateTimeToDate(endAtIso);
    if (!start || !end || end.getTime() <= start.getTime()) {
      return 1;
    }
    return Math.max(
      1,
      Math.ceil((end.getTime() - start.getTime()) / (24 * 60 * 60 * 1000))
    );
  }

  private static assetRequestQuantity(request: ContractTypes.AssetMemberRequestDTO): number {
    return Math.max(1, Math.trunc(Number(request.booking?.quantity) || 0));
  }

  private static isPricingWindowOverlap(
    request: ContractTypes.AssetMemberRequestDTO,
    startAtIso: string,
    endAtIso: string
  ): boolean {
    const requestStart = this.parseLocalDateMs(request.booking?.startAtIso);
    const requestEnd = this.parseLocalDateMs(request.booking?.endAtIso);
    const windowStart = this.parseLocalDateMs(startAtIso);
    const windowEnd = this.parseLocalDateMs(endAtIso);
    if (requestStart !== null && requestEnd !== null && windowStart !== null && windowEnd !== null) {
      return requestStart < windowEnd && windowStart < requestEnd;
    }
    const requestWindow = [
      `${request.booking?.eventId ?? ''}`.trim(),
      `${request.booking?.subEventId ?? ''}`.trim(),
      `${request.booking?.slotKey ?? ''}`.trim(),
      `${request.booking?.timeframe ?? ''}`.trim()
    ].filter(Boolean).join('|');
    const targetWindow = [startAtIso.trim(), endAtIso.trim()].filter(Boolean).join('|');
    if (requestWindow && targetWindow) {
      return requestWindow === targetWindow;
    }
    return true;
  }

  private static parseLocalDateMs(value: string | null | undefined): number | null {
    const parsed = AppUtils.isoLocalDateTimeToDate(`${value ?? ''}`.trim());
    return parsed ? parsed.getTime() : null;
  }

  private static hasMeaningfulPricingContent(
    source: Readonly<Record<string, unknown>>
  ): boolean {
    const basePrice = this.normalizeMoney(source['basePrice'] ?? source['amount']) ?? 0;
    const quantityRules = Array.isArray(source['quantityRules']) ? source['quantityRules'].length : 0;
    const demandRules = Array.isArray(source['demandRules']) ? source['demandRules'].length : 0;
    const timeRules = Array.isArray(source['timeRules']) ? source['timeRules'].length : 0;
    const slotOverrides = Array.isArray(source['slotOverrides']) ? source['slotOverrides'].length : 0;
    const cancellationPolicySource = (typeof source['cancellationPolicy'] === 'object' && source['cancellationPolicy'] !== null)
      ? source['cancellationPolicy'] as Record<string, unknown>
      : {};
    const cancellationRules = Array.isArray(cancellationPolicySource['rules']) ? cancellationPolicySource['rules'].length : 0;
    const audienceSource = (typeof source['audience'] === 'object' && source['audience'] !== null)
      ? source['audience'] as Record<string, unknown>
      : {};
    const promoCodes = Array.isArray(audienceSource['promoCodes']) ? audienceSource['promoCodes'].length : 0;
    const memberPrice = this.normalizeMoney(audienceSource['memberPrice']);
    const vipPrice = this.normalizeMoney(audienceSource['vipPrice']);
    const inviteOnlyDiscount = this.normalizePercent(audienceSource['inviteOnlyDiscountPercent']);

    return basePrice > 0
      || demandRules > 0
      || quantityRules > 0
      || timeRules > 0
      || cancellationRules > 0
      || slotOverrides > 0
      || promoCodes > 0
      || memberPrice !== null
      || vipPrice !== null
      || inviteOnlyDiscount !== null;
  }

  static slotOverrideFromReference(
    reference: ContractTypes.PricingSlotReference,
    price: number | null = null,
    currency = 'USD'
  ): ContractTypes.PricingSlotOverride {
    return {
      id: `slot-override-${reference.id}`,
      slotId: reference.id,
      label: reference.label,
      startAt: reference.startAt ?? null,
      endAt: reference.endAt ?? null,
      price,
      currency
    };
  }

  static slotCatalogFromEventSlotTemplates(
    slots: readonly Pick<ContractTypes.EventSlotTemplateDTO, 'id' | 'startAt'>[]
  ): ContractTypes.PricingSlotReference[] {
    return slots.map((slot, index) => ({
      id: `${slot.id ?? `slot-${index + 1}`}`.trim() || `slot-${index + 1}`,
      label: `Slot ${index + 1}`,
      startAt: `${slot.startAt ?? ''}`.trim() || null,
      endAt: null
    }));
  }

  private static allowedChargeTypesForContext(
    context: 'event' | 'asset' | 'subevent',
    allowSlotFeatures: boolean,
    override?: readonly AppConstants.PricingChargeType[]
  ): readonly AppConstants.PricingChargeType[] {
    const normalizedOverride = (override ?? []).filter((value, index, source) =>
      (value === 'per_attendee' || value === 'per_booking' || value === 'per_slot')
      && source.indexOf(value) === index
    );
    if (normalizedOverride.length > 0) {
      return allowSlotFeatures
        ? normalizedOverride
        : normalizedOverride.filter(value => value !== 'per_slot');
    }

    const defaults: AppConstants.PricingChargeType[] = context === 'asset'
      ? ['per_booking', 'per_attendee']
      : ['per_attendee', 'per_booking'];
    if (allowSlotFeatures) {
      defaults.push('per_slot');
    }
    return defaults;
  }

  private static sanitizeRuleScope<T extends { appliesTo: AppConstants.PricingRuleScope; slotIds: string[] }>(
    rule: T,
    slotCatalogIds: ReadonlySet<string>,
    allowSlotFeatures: boolean
  ): T {
    if (!allowSlotFeatures || slotCatalogIds.size === 0 || rule.appliesTo !== 'selected_slots') {
      return {
        ...rule,
        appliesTo: 'all_slots',
        slotIds: []
      };
    }

    const slotIds = (rule.slotIds ?? [])
      .map(item => this.normalizeText(item))
      .filter(item => slotCatalogIds.has(item));

    if (slotIds.length === 0) {
      return {
        ...rule,
        appliesTo: 'all_slots',
        slotIds: []
      };
    }

    return {
      ...rule,
      slotIds
    };
  }

  private static normalizeDemandRules(value: unknown): ContractTypes.PricingDemandRule[] {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map((entry, index) => {
      const source = (typeof entry === 'object' && entry !== null) ? entry as Record<string, unknown> : {};
      return {
        id: this.normalizeText(source['id']) || `demand-rule-${index + 1}`,
        operator: this.normalizeDemandOperator(source['operator']) ?? 'gte',
        capacityFilledPercent: this.normalizePercent(source['capacityFilledPercent']) ?? 50,
        action: this.normalizeAction(source['action'], source['actionKind'], source['value']),
        appliesTo: this.normalizeRuleScope(source['appliesTo']) ?? 'all_slots',
        slotIds: this.normalizeStringArray(source['slotIds'])
      };
    });
  }

  private static normalizeQuantityRules(value: unknown): ContractTypes.PricingQuantityRule[] {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map((entry, index) => {
      const source = (typeof entry === 'object' && entry !== null) ? entry as Record<string, unknown> : {};
      return {
        id: this.normalizeText(source['id']) || `quantity-rule-${index + 1}`,
        minQuantity: this.normalizePositiveInteger(source['minQuantity'] ?? source['quantity']) ?? 2,
        action: this.normalizeAction(source['action'], source['actionKind'], source['value'])
      };
    });
  }

  private static normalizeTimeRules(value: unknown): ContractTypes.PricingTimeRule[] {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map((entry, index) => {
      const source = (typeof entry === 'object' && entry !== null) ? entry as Record<string, unknown> : {};
      return {
        ...this.normalizeTimeRuleDateRange({
          id: this.normalizeText(source['id']) || `time-rule-${index + 1}`,
          trigger: this.normalizeTimeTrigger(source['trigger']) ?? 'days_before_start',
          offsetValue: this.normalizeOffset(source['offsetValue']),
          specificDateStart: this.normalizeDate(source['specificDateStart']),
          specificDateEnd: this.normalizeDate(source['specificDateEnd']),
          action: this.normalizeAction(source['action'], source['actionKind'], source['value']),
          appliesTo: this.normalizeRuleScope(source['appliesTo']) ?? 'all_slots',
          slotIds: this.normalizeStringArray(source['slotIds'])
        })
      };
    });
  }

  private static normalizeCancellationPolicy(value: unknown): ContractTypes.PricingCancellationPolicy {
    const source = (typeof value === 'object' && value !== null) ? value as Record<string, unknown> : {};
    const rules = this.normalizeCancellationRules(source['rules']);
    return {
      enabled: this.normalizeBoolean(source['enabled'], rules.length > 0),
      rules
    };
  }

  private static normalizeCancellationRules(value: unknown): ContractTypes.PricingCancellationRule[] {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map((entry, index) => {
      const source = (typeof entry === 'object' && entry !== null) ? entry as Record<string, unknown> : {};
      const refundKind = this.normalizeCancellationRefundKind(source['refundKind']) ?? 'percent';
      return {
        id: this.normalizeText(source['id']) || `cancellation-rule-${index + 1}`,
        offsetUnit: this.normalizeCancellationUnit(source['offsetUnit']) ?? 'days',
        offsetValue: this.normalizeOffset(source['offsetValue']),
        refundKind,
        refundValue: refundKind === 'percent'
          ? this.normalizePercent(source['refundValue'])
          : refundKind === 'fixed_amount'
            ? this.normalizeMoney(source['refundValue'])
            : null
      };
    });
  }

  private static normalizeSlotOverrides(value: unknown): ContractTypes.PricingSlotOverride[] {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map((entry, index) => {
      const source = (typeof entry === 'object' && entry !== null) ? entry as Record<string, unknown> : {};
      return {
        id: this.normalizeText(source['id']) || `slot-override-${index + 1}`,
        slotId: this.normalizeText(source['slotId']) || null,
        label: this.normalizeText(source['label']) || `Slot ${index + 1}`,
        startAt: this.normalizeText(source['startAt']) || null,
        endAt: this.normalizeText(source['endAt']) || null,
        price: this.normalizeMoney(source['price']),
        currency: this.normalizeCurrency(source['currency']) || null
      };
    });
  }

  private static normalizePromoCodes(
    value: unknown,
    preserveEmpty = false
  ): ContractTypes.PricingPromoCode[] {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map((entry, index) => {
      const source = (typeof entry === 'object' && entry !== null) ? entry as Record<string, unknown> : {};
      return {
        id: this.normalizeText(source['id']) || `promo-code-${index + 1}`,
        code: this.normalizeText(source['code']).toUpperCase(),
        action: this.normalizeAction(source['action'], source['actionKind'], source['value'])
      };
    }).filter(item => preserveEmpty || item.code.length > 0);
  }

  private static normalizeAction(
    actionValue: unknown,
    actionKindValue: unknown,
    rawValue: unknown
  ): ContractTypes.PricingAction {
    const source = (typeof actionValue === 'object' && actionValue !== null) ? actionValue as Record<string, unknown> : {};
    return {
      kind: this.normalizeActionKind(source['kind'] ?? actionKindValue) ?? 'increase_percent',
      value: this.normalizeMoney(source['value'] ?? rawValue) ?? 0
    };
  }

  private static normalizeStringArray(value: unknown): string[] {
    if (!Array.isArray(value)) {
      return [];
    }
    return value
      .map(item => this.normalizeText(item))
      .filter((item, index, source) => item.length > 0 && source.indexOf(item) === index);
  }

  private static normalizeBoolean(value: unknown, fallback = false): boolean {
    if (typeof value === 'boolean') {
      return value;
    }
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (normalized === 'true' || normalized === 'on' || normalized === 'enabled') {
        return true;
      }
      if (normalized === 'false' || normalized === 'off' || normalized === 'disabled') {
        return false;
      }
    }
    return fallback;
  }

  private static normalizeText(value: unknown): string {
    return typeof value === 'string' ? value.trim() : '';
  }

  private static normalizeMoney(value: unknown): number | null {
    if (value === null || value === undefined || value === '') {
      return null;
    }
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) {
      return null;
    }
    return Math.round(parsed * 100) / 100;
  }

  private static normalizePercent(value: unknown): number | null {
    const parsed = this.normalizeMoney(value);
    if (parsed === null) {
      return null;
    }
    return Math.max(0, Math.min(100, parsed));
  }

  private static normalizePositiveInteger(value: unknown): number | null {
    const parsed = this.normalizeMoney(value);
    if (parsed === null) {
      return null;
    }
    return Math.max(1, Math.trunc(parsed));
  }

  private static normalizeOffset(value: unknown): number | null {
    const parsed = this.normalizeMoney(value);
    if (parsed === null) {
      return null;
    }
    return Math.max(0, parsed);
  }

  private static normalizeCurrency(value: unknown): string {
    return this.normalizeText(value).toUpperCase().slice(0, 8);
  }

  private static normalizeCancellationUnit(value: unknown): AppConstants.PricingCancellationUnit | null {
    const normalized = this.normalizeText(value);
    return normalized === 'hours' || normalized === 'days' || normalized === 'weeks' || normalized === 'months'
      ? normalized
      : null;
  }

  private static normalizeCancellationRefundKind(value: unknown): AppConstants.PricingCancellationRefundKind | null {
    const normalized = this.normalizeText(value);
    return normalized === 'percent'
      || normalized === 'fixed_amount'
      || normalized === 'full'
      || normalized === 'none'
      ? normalized
      : null;
  }

  private static normalizeDate(value: unknown): string | null {
    const normalized = this.normalizeText(value);
    return normalized.length > 0 ? normalized : null;
  }

  private static normalizeTimeRuleDateRange(rule: ContractTypes.PricingTimeRule): ContractTypes.PricingTimeRule {
    const start = rule.specificDateStart;
    const end = rule.specificDateEnd;
    if (!start && !end) {
      return {
        ...rule,
        specificDateStart: null,
        specificDateEnd: null
      };
    }
    if (start && !end) {
      return {
        ...rule,
        specificDateStart: start,
        specificDateEnd: start
      };
    }
    if (!start && end) {
      return {
        ...rule,
        specificDateStart: end,
        specificDateEnd: end
      };
    }
    if ((start ?? '') > (end ?? '')) {
      return {
        ...rule,
        specificDateStart: end,
        specificDateEnd: start
      };
    }
    return rule;
  }

  private static normalizeMode(value: unknown): AppConstants.PricingMode {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'demand-based' || normalized === 'demand') {
      return 'demand-based';
    }
    if (normalized === 'time-based' || normalized === 'time') {
      return 'time-based';
    }
    if (normalized === 'hybrid') {
      return 'hybrid';
    }
    return 'fixed';
  }

  private static normalizeTaxMode(value: unknown): AppConstants.PricingTaxMode | null {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'included') {
      return 'included';
    }
    if (normalized === 'excluded') {
      return 'excluded';
    }
    return null;
  }

  private static normalizeChargeType(value: unknown): AppConstants.PricingChargeType | null {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'per_booking' || normalized === 'booking') {
      return 'per_booking';
    }
    if (normalized === 'per_slot' || normalized === 'slot') {
      return 'per_slot';
    }
    if (normalized === 'per_attendee' || normalized === 'attendee' || normalized === 'person') {
      return 'per_attendee';
    }
    return null;
  }

  private static normalizeRounding(value: unknown): AppConstants.PricingRoundingMode | null {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'whole' || normalized === 'whole_number') {
      return 'whole';
    }
    if (normalized === 'half' || normalized === '0.5') {
      return 'half';
    }
    if (normalized === 'none' || normalized === 'no_rounding') {
      return 'none';
    }
    return null;
  }

  private static normalizeActionKind(value: unknown): AppConstants.PricingRuleActionKind | null {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'set_exact_price' || normalized === 'exact_price') {
      return 'set_exact_price';
    }
    if (normalized === 'decrease_percent' || normalized === 'discount') {
      return 'decrease_percent';
    }
    if (normalized === 'decrease_amount' || normalized === 'discount_amount' || normalized === 'fixed_discount') {
      return 'decrease_amount';
    }
    if (normalized === 'increase_amount' || normalized === 'surcharge_amount' || normalized === 'fixed_increase') {
      return 'increase_amount';
    }
    if (normalized === 'increase_percent' || normalized === 'increase') {
      return 'increase_percent';
    }
    return null;
  }

  private static normalizeRuleScope(value: unknown): AppConstants.PricingRuleScope | null {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'selected_slots' || normalized === 'selected') {
      return 'selected_slots';
    }
    if (normalized === 'all_slots' || normalized === 'all') {
      return 'all_slots';
    }
    return null;
  }

  private static normalizeDemandOperator(value: unknown): AppConstants.PricingDemandOperator | null {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'lte' || normalized === '<=' || normalized === 'lt') {
      return 'lte';
    }
    if (normalized === 'gte' || normalized === '>=' || normalized === 'gt') {
      return 'gte';
    }
    return null;
  }

  private static normalizeTimeTrigger(value: unknown): AppConstants.PricingTimeRuleTrigger | null {
    const normalized = this.normalizeText(value).toLowerCase();
    if (normalized === 'hours_before_start' || normalized === 'hours') {
      return 'hours_before_start';
    }
    if (normalized === 'specific_date' || normalized === 'date') {
      return 'specific_date';
    }
    if (normalized === 'days_before_start' || normalized === 'days') {
      return 'days_before_start';
    }
    return null;
  }
}
